// Extract post data from Airtable record
const item = $input.first();
const fields = item.json.fields || item.json;

// Parse content brief to extract slot if embedded
const brief = fields['Content Brief'] || '';
const slotMatch = brief.match(/Slot: (morning|evening)/i);
const slot = slotMatch ? slotMatch[1] : 'morning';
const cleanBrief = brief.replace(/ \| Slot: (morning|evening)/i, '').trim();

return [{
  json: {
    recordId: item.json.id || '',
    title: fields.Title || 'Dorothy Dean Designs Post',
    pillar: fields.Pillar || '',
    hookNumber: fields['Hook #'] || '',
    contentBrief: cleanBrief,
    videoFormat: fields['Video Format'] || '30-60s Lifestyle/Styling',
    date: fields.Date || fields['Scheduled Date'] || '',
    slot
  }
}];

// Build the Gemini REST API request body
const postData = $input.first().json;

const systemPrompt = 'You are a content strategist for Dorothy Dean Designs, a faith-based lifestyle apparel brand rooted in Christian values, created for Black women. The brand voice is warm, empowering, sisterly, and rooted in faith — never preachy, always genuine. Captions should feel like they come from a real woman who loves God and loves fashion. Speak directly to the target audience: Black Christian women ages 18-45 who express their faith through their style. Always return valid JSON only.';

const slotDescription = postData.slot === 'morning'
  ? 'devotional/inspirational tone — start the day with faith'
  : 'styling/lifestyle tone — show the product in real life';

const userPrompt = `Generate 2 social media captions for a Dorothy Dean Designs post.\n\nPost Details:\n- Title: ${postData.title}\n- Content Pillar: ${postData.pillar}\n- Hook: ${postData.hookNumber}\n- Content Brief: ${postData.contentBrief}\n- Video Format: ${postData.videoFormat}\n- Posting Slot: ${postData.slot} (${slotDescription})\n\nReturn ONLY valid JSON with these exact keys (no markdown, no code blocks):\n{\n  "tiktok": "Hook-first caption. Max 150 chars. Punchy, faith-forward, relatable. End with 1-2 hashtags: #DorothyDeanDesigns and one relevant tag like #FaithFashion, #ChristianGirl, or #BlackChristian",\n  "instagram": "Warm, sisterly 2-4 sentence caption that feels like a text from a close friend who loves Jesus. Start with a bold question or statement. Weave in faith naturally — not preachy. Close with an engaging question or soft CTA (like 'link in bio'). Include 5-8 hashtags on a new line: #DorothyDeanDesigns #FaithFashion #ChristianApparel #BlackChristian #WearYourFaith and 2-3 relevant trending tags."\n}`;

const requestBody = {
  system_instruction: {
    parts: [{ text: systemPrompt }]
  },
  contents: [{
    role: 'user',
    parts: [{ text: userPrompt }]
  }],
  generationConfig: {
    maxOutputTokens: 1024,
    temperature: 0.75
  }
};

return [{
  json: {
    ...postData,
    geminiRequestBody: requestBody
  }
}];

const geminiOutput = $input.first().json;
const postData = $('Extract Post Data').first().json;

// Handle Gemini REST API response format
let responseText = '';
if (geminiOutput.candidates && geminiOutput.candidates[0]) {
  const candidate = geminiOutput.candidates[0];
  if (candidate.content && candidate.content.parts && candidate.content.parts[0]) {
    responseText = candidate.content.parts[0].text || '';
  }
} else if (typeof geminiOutput === 'string') {
  responseText = geminiOutput;
} else if (geminiOutput.text) {
  responseText = String(geminiOutput.text);
} else {
  responseText = JSON.stringify(geminiOutput);
}

let captionsData;
try {
  let jsonMatch = responseText.match(/```json\s*([\s\S]*?)\s*```/);
  if (!jsonMatch) jsonMatch = responseText.match(/```\s*([\s\S]*?)\s*```/);
  if (!jsonMatch) jsonMatch = responseText.match(/(\{[\s\S]*\})/);
  const jsonString = jsonMatch ? jsonMatch[1].trim() : responseText.trim();
  captionsData = JSON.parse(jsonString);
} catch (e) {
  captionsData = {
    tiktok: `${postData.title} — wear your faith out loud. #DorothyDeanDesigns #FaithFashion`,
    instagram: `Faith is your foundation, style is your statement. ✨ ${postData.contentBrief} Every piece from Dorothy Dean Designs is made for the woman who knows whose she is. Which look speaks to your spirit? 👇\n\n#DorothyDeanDesigns #FaithFashion #ChristianApparel #BlackChristian #WearYourFaith #ChristianGirl #FaithStyle`
  };
}

return [{
  json: {
    recordId: postData.recordId,
    tiktokCaption: captionsData.tiktok || '',
    instagramCaption: captionsData.instagram || ''
  }
}];
